function archiveOrder(id: string): boolean {
  return id.length > 0;
}

function fileCacheKey(path: string, fallback: string): string {
  return `file:${path}:${fallback}`;
}

function add(a: number, b: number): number {
  return a + b;
}

function kiroWorkflowsUnreadableFix(settingsPath: string): string {
  return `fix the error in ${settingsPath}`;
}

function anomalyRuleId(
  detectorId: string,
  classifierId: string,
): string {
  return `anomaly__${detectorId}__${classifierId}`;
}

function catalogKey(
  detectorId: string,
  classifierId: string,
