  return `${detectorId}__${classifierId}`;
}

function isValueStringEmpty(value: string): boolean {
  return value === '';
}

const DUPLICATED_CONTROLLER_NAME: (name: string) => string = (
  name: string,
): string => `Two controllers cannot have the same name: ${name}`;

function canRestoreScrollOffset(savedOffset: number, contentHeight: number): boolean {
  return savedOffset <= contentHeight;
}

function controllerKey( name: string ): string {
  return '$' + name + 'Controller';
}

function createSkillPackageHubUrl(endpoint: string, packageName: string): string {
    return `https://hub.${endpoint}/package/${packageName}`;
}

function ruleId(packId: string, ruleName: string): string {
  return `${packId}:${ruleName}`;
}

function conversationTabId(entryId: string): string {
  return `entry:${entryId}`;
}

function calc(exp: string): string {
  return `calc(${exp})`;
}

function cacheDigestPath(path: string): string {
  return `${path}.sha256`;
}

function modelPickerPageSize(height: number): number {
  // Border, title, search, selected-detail, and controls always stay visible.
  return Math.max(1, height - 6);
}

function pickerPageSize(height: number): number {
  return Math.max(1, height - 5);
}

function gopFrames(keyframeIntervalSec: number, fps: number): number {
  return Math.max(1, Math.round(fps * keyframeIntervalSec));
}

function sign(x: number): number {
  return (x > 0 ? 1 : 0) - (x < 0 ? 1 : 0) || +x
}

function clamp01(val: number): number {
  return Math.min(1, Math.max(0, val));
}

function clampToUnit(value: number): number {
  // NaN (e.g. from pointer math over a zero-size, hidden container) must not
  // escape into seek positions -- treat it as 0.
  if (Number.isNaN(value)) return 0
  if (value < 0) return 0
  if (value > 1) return 1
  return value
}

function clampRatio(ratio: number): number {
  if (Number.isNaN(ratio)) {
    return 0;
  }
  if (ratio < 0) {
    return 0;
  }
  if (ratio > 1) {
    return 1;
  }
  return ratio;
}

function normalizeAlpha(alpha: number): number {
  alpha = Math.round(alpha * 100) / 100
  return alpha > 1 ? 1 : alpha < 0 ? 0 : alpha
}

function clamp01(value: number): number {
	return Math.min(1, Math.max(0, value));
}

function clamp01(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.min(1, value)) : 0;
}

function clamp01(value: number): number {
  if (value < 0) return 0;
  if (value > 1) return 1;
  return value;
}
